export function runAgentSurfaceAdversarialCorpus(){let passed=0;const results=CASES.map(([expected,surface],index)=>{const report=scanAgentSurface(surface);const detected=report.findings.some(x=>x.code===expected);if(detected)passed++;return{id:`AS-${String(index+1).padStart(3,'0')}`,expected,detected};});const payload={schemaVersion:1,cases:CASES.length,passed,missed:CASES.length-passed,results,corpusSha256:canonicalSha256(CASES)};return Object.freeze({...payload,reportSha256:canonicalSha256(payload)});}
